From 3dddcf42f213ea5028bc4e558e78bed4a5f01321 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:46:43 +0100
Subject: [PATCH] shell/panelview: Ignore the Leave event sent when a popup
 opens

Qt sends the panel a Leave when one of its menus grabs the pointer, and no
Enter once it closes, so closing the Global Menu with Esc hid an auto-hide
panel still under the pointer. Ignore that one Leave while the menu is up.

BUG: 473454
---
 shell/panelview.cpp | 16 ++++++++++++++++
 shell/panelview.h   |  1 +
 2 files changed, 17 insertions(+)

diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..853aefae94 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -1181,6 +1181,22 @@ bool PanelView::event(QEvent *e)
         break;

     case QEvent::Leave:
+        // Qt sends a Leave when a popup grabs the pointer, even though it is still on the panel,
+        // and no Enter when the popup closes
+        if (m_containsMouse && !m_popupGrabWatcher) {
+            const auto windows = qApp->topLevelWindows();
+            const auto popup = std::ranges::find_if(windows, [this](QWindow *window) {
+                // menus whose transient parent isn't shown are attached by Qt to the window that got the input
+                const QWindow *parent = window->transientParent();
+                return window->type() == Qt::Popup && window->isVisible() && (parent == this || !parent || !parent->isVisible());
+            });
+            if (popup != windows.end()) {
+                m_popupGrabWatcher = connect(*popup, &QWindow::visibleChanged, this, [this] {
+                    disconnect(m_popupGrabWatcher);
+                });
+                break;
+            }
+        }
         m_containsMouse = false;
         if (edgeActivated()) {
             m_unhideTimer.start();
diff --git a/shell/panelview.h b/shell/panelview.h
index eb276bf7f6..a2c3bd465d 100644
--- a/shell/panelview.h
+++ b/shell/panelview.h
@@ -366,6 +366,7 @@ private:
     QPointer<QScreen> m_lastScreen;
     QPointer<QScreen> m_screenToFollow;
     QMetaObject::Connection m_transientWindowVisibleWatcher;
+    QMetaObject::Connection m_popupGrabWatcher;
     AutoHideScreenEdge *m_autoHideScreenEdge = nullptr;

     static const int STRUTSTIMERDELAY = 200;
